import { test, expect } from '@playwright/test';

// [P0-5] Browser-level proof of the PWA shell. Runs against the built + previewed
// app (the service worker is only generated by `vite build`). Run: npm run test:e2e

// The service worker is registered by the APP bundle (main.tsx → registerServiceWorker); `/` is now the
// prerendered marketing landing with NO app code (it loads landing-*.js, not the app), so it never
// registers a worker. Exercise the SW where it actually lives: /app. (These two tests used to goto('/')
// from when `/` WAS the app shell, before the landing was split out to marketing-only.)
test('registers and activates a service worker', async ({ page }) => {
  await page.goto('/app');
  const active = await page.evaluate(async () => {
    const reg = await navigator.serviceWorker.ready;
    return Boolean(reg.active);
  });
  expect(active).toBe(true);
});

test('links a web manifest (installability prerequisite)', async ({ page }) => {
  await page.goto('/');
  const href = await page.getAttribute('link[rel="manifest"]', 'href');
  expect(href).toBeTruthy();
});

// [SW-UPDATE] An in-progress voice note lives in the outbox (IndexedDB 'tovira-capture'/'recordings').
// Accepting the "New version — Reload" prompt reloads the page; a service-worker swap and a reload
// never clear IndexedDB, so the capture must still be there afterwards. Proven in a real browser.
test('an in-progress voice note in the outbox survives a reload (the update path)', async ({ page }) => {
  await page.goto('/app');
  await page.evaluate(() => navigator.serviceWorker.ready);

  await page.evaluate(async () => {
    await new Promise<void>((resolve, reject) => {
      const req = indexedDB.open('tovira-capture', 1);
      req.onupgradeneeded = () => {
        if (!req.result.objectStoreNames.contains('recordings')) req.result.createObjectStore('recordings', { keyPath: 'id' });
      };
      req.onerror = () => reject(req.error);
      req.onsuccess = () => {
        const db = req.result;
        const tx = db.transaction('recordings', 'readwrite');
        tx.objectStore('recordings').put({ id: 'zz-uatbot-sw', clientId: 'zz', blob: new Blob(['hello']), createdAt: Date.now(), attempts: 0 });
        tx.oncomplete = () => { db.close(); resolve(); };
        tx.onerror = () => reject(tx.error);
      };
    });
  });

  await page.reload(); // what accepting the update prompt does
  await page.evaluate(() => navigator.serviceWorker.ready);

  const survived = await page.evaluate(async () =>
    new Promise<boolean>((resolve, reject) => {
      const req = indexedDB.open('tovira-capture', 1);
      req.onerror = () => reject(req.error);
      req.onsuccess = () => {
        const g = req.result.transaction('recordings', 'readonly').objectStore('recordings').getAll();
        g.onsuccess = () => { req.result.close(); resolve((g.result as Array<{ id: string }>).some((r) => r.id === 'zz-uatbot-sw')); };
        g.onerror = () => reject(g.error);
      };
    }),
  );
  expect(survived).toBe(true);
});

test('app shell still renders offline (no blank page)', async ({ page, context }) => {
  await page.goto('/app'); // the app shell + SW live here (see note above); `/` is marketing-only
  // Let the service worker install and precache the shell.
  await page.evaluate(() => navigator.serviceWorker.ready);
  await page.waitForTimeout(1500);

  await context.setOffline(true);
  await page.reload();

  // The cached shell renders the login screen even with no network.
  await expect(page.getByRole('heading', { name: 'Tovira' })).toBeVisible();
});
